<script setup lang="ts">
import {computed,ref,shallowRef,watch,onMounted,onBeforeUnmount,nextTick,useId} from 'vue';
import {createTaskGraphLayoutPipeline} from '../task-graph-layout-client';
import {graphGroupKey,sameGraphIdentity,type GraphGrouping} from '../../shared/task-graph-contract';
import {graphRenderCandidates,graphRoutePath,graphDirectRelations,projectGraphViewport,type GraphLayout} from '../../shared/task-graph-layout';
import type {AssembledGraphSnapshot} from '../../shared/task-graph-transport';
import type {GraphDateReadResult} from '../../shared/task-graph-dates';
import {graphGroupLabels,graphDeclaredStatus,graphGroupDateSummaries,graphDateYearContext,graphDateShortLabel} from '../task-graph-overview';
import {sessionGraphNavigationHistory,admittedGraphSelection,clampGraphZoom,graphCenteredScroll,graphMinimapPath,type GraphNavigationView} from '../task-graph-navigation';
import GraphInfoTooltip from './GraphInfoTooltip.vue';
import {createGraphPan} from '../task-graph-pan';
import {createGraphZoom} from '../task-graph-zoom';
import {graphRelationSet,graphRelationLocation} from '../task-graph-relations';
import {linkedDateKst} from '../../shared/linked-date-format';
import TaskGraphOverview from './TaskGraphOverview.vue';
const props=defineProps<{projectId:string;dagId?:string;sourceKey:string;current:boolean;active:boolean;selectedId?:string|null;detailOpen?:boolean}>();
const emit=defineEmits<{select:[id:string];selectionRestore:[id:string|null,detailOpen:boolean];openGroup:[key:string|null,grouping:GraphGrouping]}>();
const pipeline=createTaskGraphLayoutPipeline(window.noteApp);
const grouping=ref<GraphGrouping>('prefix'),groupKey=ref<string|null>(null),snapshot=shallowRef<AssembledGraphSnapshot|null>(null),layout=shallowRef<GraphLayout|null>(null),dates=shallowRef<GraphDateReadResult|null>(null);
const loading=ref(false),error=ref(''),dateError=ref(false),hidden=ref(document.hidden),pane=ref<HTMLElement|null>(null),minimapCanvas=ref<SVGSVGElement|null>(null),search=ref(''),status=ref('all'),showFilter=ref(false);
let generation=0,dateRequest:string|null=null;
const history=sessionGraphNavigationHistory;
let savedView:GraphNavigationView|undefined;
let navigation=0;
const showRelations=ref(false),relationsDismissed=ref(false),focusReturnId=ref<string|null>(null);
const hoveredId=ref<string|null>(null),relationFocus=ref<string|null>(null),boundaryPage=ref(1);
let hoverTimer:ReturnType<typeof setTimeout>|undefined;
const relationReturn=shallowRef<{group:string|null;mode:GraphGrouping;id:string|null;x:number;y:number;zoom:number;status:string}|null>(null);
const relationId=computed(()=>relationsDismissed.value?null:hoveredId.value??relationFocus.value??props.selectedId??null);
const relationSet=computed(()=>layout.value&&relationId.value?graphRelationSet(layout.value,relationId.value):null);
const boundaryRelations=computed(()=>!layout.value?[]:(relationSet.value?.relations??[]).map(relation=>({...relation,...graphRelationLocation(layout.value!,relation,viewport.value,filtered.value)})).filter(relation=>relation.kind!=='visible'));
watch(relationId,()=>{boundaryPage.value=1;});
watch(()=>boundaryRelations.value.length,()=>{boundaryPage.value=Math.max(1,Math.min(boundaryPage.value,Math.ceil(boundaryRelations.value.length/6)));});
let restoringDismissedFocus=false;
async function dismissRelations(event:KeyboardEvent){
 if(event.key!=='Escape'||!relationId.value)return;
 const anchor=relationId.value,epoch=generation;
 const removedControl=!!(document.activeElement as HTMLElement|null)?.closest?.('.boundary-relations, .density-relations, [data-relation-dismiss-focus]');
 event.preventDefault();event.stopPropagation();keepHover();hoveredId.value=null;relationFocus.value=null;relationsDismissed.value=true;showRelations.value=false;
 if(!removedControl)return;
 if(layout.value?.positionById.has(anchor))focusedId.value=anchor;
 await nextTick();if(epoch!==generation||!usable.value)return;
 const target=Array.from(pane.value?.querySelectorAll<HTMLButtonElement>('[data-graph-task]')??[]).find(el=>el.dataset.graphTask===anchor)??pane.value;
 restoringDismissedFocus=true;try{target?.focus({preventScroll:true});}finally{restoringDismissedFocus=false;}
}
function keepHover(){if(hoverTimer)clearTimeout(hoverTimer);hoverTimer=undefined;}
function enterNode(id:string){relationsDismissed.value=false;keepHover();hoveredId.value=id;}
function leaveNode(){keepHover();hoverTimer=setTimeout(()=>{hoveredId.value=null;hoverTimer=undefined;},180);}
function focusNode(id:string){if(restoringDismissedFocus){focusedId.value=id;return;}relationsDismissed.value=false;keepHover();hoveredId.value=null;focusedId.value=id;relationFocus.value=id;}
function leaveRelationControls(event:FocusEvent){const next=event.relatedTarget as HTMLElement|null;if(!next?.closest?.('[data-relation-controls]')&&!next?.dataset?.graphTask)relationFocus.value=null;}
function blurNode(event:FocusEvent){focusReturnId.value=null;const next=event.relatedTarget as HTMLElement|null;if(!next?.closest?.('[data-relation-controls]'))relationFocus.value=null;}
function nodeRelationClass(id:string){if(!relationId.value)return '';if(id===relationId.value)return 'relation-anchor';const roles=relationSet.value?.nodes.get(id);return roles?.size===2?'relation-both':roles?.has('predecessor')?'relation-predecessor':roles?.has('successor')?'relation-successor':'relation-muted';}
function edgeRelationClass(id:string){if(!relationId.value)return '';const roles=relationSet.value?.edges.get(id);return roles?.size===2?'relation-both':roles?.has('predecessor')?'relation-predecessor':roles?.has('successor')?'relation-successor':'relation-muted';}
function relationLabel(id:string){const roles=relationSet.value?.nodes.get(id);return roles?.size===2?'선행·후속':roles?.has('predecessor')?'선행':roles?.has('successor')?'후속':'';}
async function followRelation(id:string){if(!usable.value||!layout.value)return;const identity=layout.value.identity;const origin={group:groupKey.value,mode:grouping.value,id:relationId.value,x:pane.value?.scrollLeft??0,y:pane.value?.scrollTop??0,zoom:zoom.value,status:status.value};const revealed=await reveal(id);if(revealed&&usable.value&&layout.value&&sameGraphIdentity(identity,layout.value.identity)&&relationFocus.value===id)relationReturn.value=origin;}
async function returnRelation(){const prior=relationReturn.value;if(!prior||!usable.value)return;if((prior.group!==groupKey.value||prior.mode!==grouping.value)&&!await project(prior.group,prior.mode))return;const epoch=generation;zoom.value=prior.zoom;status.value=prior.status;focusedId.value=prior.id;relationFocus.value=prior.id;relationReturn.value=null;await nextTick();if(epoch!==generation||!usable.value)return;pane.value?.scrollTo({left:prior.x,top:prior.y});measure();await focusOnly(prior.id);}
async function focusOnly(id:string|null){const epoch=generation;if(!id||!usable.value||!layout.value?.positionById.has(id))return;focusReturnId.value=filtered.value&&!filtered.value.has(id)?id:null;focusedId.value=id;await nextTick();if(epoch!==generation||!usable.value)return;Array.from(pane.value?.querySelectorAll<HTMLButtonElement>('[data-graph-task]')??[]).find(el=>el.dataset.graphTask===id)?.focus({preventScroll:true});relationFocus.value=id;}

const focusedId=ref<string|null>(null),relationPage=ref(1),searchPage=ref(1),selectionNotice=ref('');
function rememberView(){if(layout.value){history.save(layout.value,{zoom:zoom.value,x:pane.value?.scrollLeft??0,y:pane.value?.scrollTop??0,selectedId:props.selectedId??null,detailOpen:!!props.detailOpen,status:status.value});savedView=history.get(layout.value.identity,layout.value.grouping,layout.value.groupKey);}}
function restoreSelection(prior:GraphNavigationView|undefined,next:GraphLayout){const id=admittedGraphSelection(prior,next,snapshot.value?.metadata.diagnostics.duplicateIds??[]);selectionNotice.value=prior?.selectedId&&!id?'이전 선택 작업이 삭제되었거나 중복되어 선택을 해제했습니다.':'';emit('selectionRestore',id,!!id&&!!prior?.detailOpen);}
const overview=ref<InstanceType<typeof TaskGraphOverview>|null>(null);
const marker=useId().replace(/:/g,'');
const markerTones={default:'var(--app-primary)','relation-predecessor':'var(--app-info-text)','relation-successor':'var(--app-warning-text)','relation-both':'var(--app-primary)'};
function edgeMarker(id:string){const role=edgeRelationClass(id);return marker+'-'+(role in markerTones?role:'default');}
const cyclePage=ref(1),cycleMemberPage=ref(1);
const sourceCycles=computed(()=>layout.value?.sourceCycles??[]);
const activeCycle=computed(()=>sourceCycles.value[cyclePage.value-1]??[]);
watch(snapshot,()=>{cyclePage.value=1;cycleMemberPage.value=1;});
watch(cyclePage,()=>{cycleMemberPage.value=1;});
// Only allowlisted transport failure codes affect presentation. Raw exceptions
// may contain private paths or source data and are never displayed.
function readFailure(failure:unknown){
 const code=failure instanceof Error?failure.message:'';
 if(code==='stale-session'||code==='source-changed')return '그래프 근거가 변경되었습니다. 최신 근거를 다시 읽어 주세요.';
 if(code==='disconnected')return '프로젝트 연결이 끊겼습니다. 연결을 복구한 뒤 다시 읽어 주세요.';
 if(code==='unauthorized')return '현재 그래프 읽기 권한을 확인할 수 없습니다. 프로젝트 접근 권한을 확인한 뒤 다시 읽어 주세요.';
 if(code==='unsupported')return '그래프가 현재 지원 범위를 넘었습니다. 소스 크기와 형식을 확인해 주세요.';
 if(code==='timeout')return '전체 그래프를 읽는 시간이 초과되었습니다. 연결과 소스를 확인한 뒤 다시 읽어 주세요.';
 if(code==='invalid-schema'||code==='invalid-result')return '그래프 응답을 검증하지 못했습니다. 최신 근거를 다시 읽어 주세요.';
 if(code==='worker-unavailable'||code==='layout-failed')return '그래프 계산을 완료하지 못했습니다. 다시 읽어 주세요.';
 return '전체 그래프를 읽지 못했습니다. 연결과 근거를 확인한 뒤 다시 시도해 주세요.';
}
const viewport=ref({x:0,y:0,width:1100,height:600}),zoom=ref(1);
const usable=computed(()=>props.active&&props.current&&!hidden.value);
const labels=computed(()=>layout.value?graphGroupLabels(layout.value):new Map<string,string>());
const orderedGroups=computed(()=>snapshot.value?[...new Set(snapshot.value.nodes.map(node=>graphGroupKey(node,grouping.value)))]:[]);
const currentGroup=computed(()=>layout.value?.groups.find(g=>g.key===groupKey.value));
const groupDates=computed(()=>layout.value?graphGroupDateSummaries(layout.value,dates.value):new Map());
const dateYear=computed(()=>graphDateYearContext([...groupDates.value.values()]));
const groupDate=computed(()=>groupDates.value.get(groupKey.value??''));
const groupStatuses=computed(()=>currentGroup.value?.declaredStatusCounts.map(s=>({...s,...graphDeclaredStatus(s.status)}))??[]);
const statuses=computed(()=>layout.value?[...new Set([...layout.value.index.nodeById.values()].map(n=>n.declaredStatus))]:[]);
const filtered=computed(()=>status.value==='all'||!layout.value?undefined:new Set([...layout.value.index.nodeById.values()].filter(n=>(n.declaredStatus??'')===status.value.slice(7)).map(n=>n.id)));
const matches=computed(()=>{const query=search.value.trim().toLocaleLowerCase();return !query||!layout.value?[]:[...layout.value.index.nodeById.values()].filter(n=>`${n.id} ${n.title??''}`.toLocaleLowerCase().includes(query));});
// These are provisional safety ceilings, not measured frame-rate promises. Dense
// candidates are reported explicitly; source semantics are never truncated.
const render=computed(()=>layout.value&&groupKey.value!==null?graphRenderCandidates(layout.value,viewport.value,{nodeBudget:600,routeBudget:2000},filtered.value):null);
function stop(){focusReturnId.value=null;relationsDismissed.value=false;generation++;navigation++;pan.reset();gestureZoom.reset();keepHover();hoveredId.value=null;relationFocus.value=null;focusedId.value=null;pipeline.cancel();if(dateRequest){void window.noteApp.cancelTaskGraphDates({requestId:dateRequest}).catch(()=>{});dateRequest=null;}loading.value=false;}
function reset(clearSelection=true){stop();relationReturn.value=null;snapshot.value=null;layout.value=null;dates.value=null;groupKey.value=null;error.value='';if(clearSelection&&(props.active&&!hidden.value||!props.current))emit('selectionRestore',null,false);dateError.value=false;}
async function readDates(value:AssembledGraphSnapshot,epoch:number){const identity=value.metadata.identity,requestId=crypto.randomUUID();dateRequest=requestId;dateError.value=false;try{const result=await window.noteApp.readTaskGraphDates({requestId,projectId:identity.projectId,dagId:identity.dagId,sessionKey:identity.sessionKey,expectedRevision:identity.revision});if(epoch!==generation||!usable.value)return;if(result.state==='unavailable'&&['stale-session','source-changed','disconnected','unauthorized'].includes(result.reason)){reset();error.value='그래프 연결 또는 읽기 권한이 변경되었습니다. '+readFailure(Error(result.reason));return;}if(result.state!=='dates'||result.requestId!==requestId||!sameGraphIdentity(result.identity,identity)){dateError.value=true;return;}const session=await window.noteApp.getTaskGraphSession({projectId:identity.projectId});if(epoch!==generation||!usable.value)return;if(!session||session.projectId!==identity.projectId||session.sessionKey!==identity.sessionKey||session.dagId!==identity.dagId){reset();error.value='근거가 변경되었습니다. 다시 읽어 주세요.';return;}dateError.value=false;dates.value=Object.freeze(result);}catch{if(epoch===generation)dateError.value=true;}finally{void window.noteApp.cancelTaskGraphDates({requestId}).catch(()=>{});if(dateRequest===requestId)dateRequest=null;}}
// A same-source resume may keep the existing reader mounted while the pipeline
// revalidates authority. Failed reads or selection admission still clear it.
async function load(preserveResumedDetail=false){
 const resumedSelection=props.selectedId;
 rememberView();reset(!preserveResumedDetail);
 if(savedView&&(savedView.previous.identity.projectId!==props.projectId||(props.dagId!==undefined&&savedView.previous.identity.dagId!==props.dagId))){savedView=props.dagId?history.latest(props.projectId,props.dagId):undefined;grouping.value=savedView?.previous.grouping??'prefix';status.value='all';search.value='';}
 if(!usable.value)return;
 if(!savedView&&props.dagId){savedView=history.latest(props.projectId,props.dagId);grouping.value=savedView?.previous.grouping??grouping.value;}
 const epoch=generation,prior=savedView;loading.value=true;
 try{const result=await pipeline.read(props.projectId,{grouping:grouping.value,groupKey:prior?.previous.groupKey??null,previous:prior?.previous});
 if(epoch!==generation||!usable.value)return;if(props.dagId&&result.layout.identity.dagId!==props.dagId)throw Error('dag-changed');let next=result.layout,key=prior?.previous.groupKey??null;
 if(key!==null&&!next.groups.some(group=>group.key===key)){next=await pipeline.layout(result.snapshot,{grouping:grouping.value,groupKey:null});key=null;}
 if(epoch!==generation||!usable.value)return;
 snapshot.value=result.snapshot;layout.value=next;groupKey.value=key;zoom.value=prior?.zoom??1;status.value=prior?.status??'all';loading.value=false;
 // The reader remains interactive during resume; a newer close wins over history.
 if(!preserveResumedDetail||(props.selectedId===resumedSelection&&props.detailOpen))restoreSelection(prior,next);await nextTick();if(epoch!==generation||!usable.value)return;
 pane.value?.scrollTo({left:prior?.x??0,top:prior?.y??0});measure();void readDates(result.snapshot,epoch);
 }catch(failure){if(epoch===generation){error.value=readFailure(failure);if(preserveResumedDetail)emit('selectionRestore',null,false);}}finally{if(epoch===generation)loading.value=false;}
}
async function project(key:string|null,mode:GraphGrouping=grouping.value,restore=true){
 if(!snapshot.value||!usable.value)return false;rememberView();stop();const epoch=generation,source=snapshot.value;
 const prior=history.get(source.metadata.identity,mode,key);loading.value=true;error.value='';emit('selectionRestore',null,false);
 try{const result=await pipeline.layout(source,{grouping:mode,groupKey:key,previous:prior?.previous});
 if(epoch!==generation||!usable.value)return false;
 layout.value=result;grouping.value=mode;groupKey.value=key;zoom.value=prior?.zoom??1;status.value=prior?.status??'all';loading.value=false;
 emit('openGroup',key,mode);if(restore)restoreSelection(prior,result);await nextTick();if(epoch!==generation||!usable.value)return false;
 pane.value?.scrollTo({left:prior?.x??0,top:prior?.y??0});measure();if(!dates.value)void readDates(source,epoch);return true;
 }catch(failure){if(epoch===generation){layout.value=null;dates.value=null;error.value=readFailure(failure);}return false;}finally{if(epoch===generation)loading.value=false;}
}
async function changeGrouping(value:GraphGrouping){if(grouping.value!==value)await project(null,value);}
const diagnosticViewport=ref(viewport.value);let diagnosticTimer:ReturnType<typeof setTimeout>|undefined;
function measure(){const el=pane.value;if(el){viewport.value={x:el.scrollLeft/zoom.value,y:el.scrollTop/zoom.value,width:el.clientWidth/zoom.value,height:el.clientHeight/zoom.value};if(diagnosticTimer)clearTimeout(diagnosticTimer);diagnosticTimer=setTimeout(()=>{diagnosticViewport.value=viewport.value;diagnosticTimer=undefined;},120);}}

let zoomTicket=0;
const gestureZoom=createGraphZoom(()=>pane.value,()=>({scale:zoom.value,left:pane.value?.scrollLeft??0,top:pane.value?.scrollTop??0}),async view=>{
 const el=pane.value,epoch=generation,ticket=++zoomTicket;zoom.value=view.scale;await nextTick();
 if(epoch!==generation||ticket!==zoomTicket||el!==pane.value)return;
 el?.scrollTo({left:view.left,top:view.top});measure();
});
async function setZoom(value:number){gestureZoom.zoomTo(value);await nextTick();}
async function fit(){if(groupKey.value===null){overview.value?.resetZoom();await nextTick();document.querySelector<HTMLElement>('[data-testid=graph-overview] .overview-scroll')?.scrollTo({left:0,top:0});return;}if(layout.value&&pane.value){await setZoom(Math.min(1,pane.value.clientWidth/layout.value.width,pane.value.clientHeight/layout.value.height));pane.value?.scrollTo({left:0,top:0});measure();}}
async function reveal(id:string){
 if(!usable.value)return;focusReturnId.value=null;const target=layout.value?.index.groupById.get(id);if(!target)return;
 if((groupKey.value!==target||loading.value)&&!await project(target,grouping.value,false))return;
 const epoch=generation,ticket=++navigation,node=layout.value?.positionById.get(id);if(!node||!pane.value)return;
 search.value='';status.value='all';zoom.value=Math.max(1,zoom.value);focusedId.value=id;relationFocus.value=id;hoveredId.value=null;
 await nextTick();if(epoch!==generation||ticket!==navigation||!usable.value)return;
 pane.value?.scrollTo(graphCenteredScroll(node,zoom.value,pane.value.clientWidth,pane.value.clientHeight));measure();await nextTick();
 if(epoch!==generation||ticket!==navigation||!usable.value)return;
 Array.from(pane.value?.querySelectorAll<HTMLButtonElement>('[data-graph-task]')??[]).find(el=>el.dataset.graphTask===id)?.focus();return true;
}
const miniPath=computed(()=>layout.value?graphMinimapPath(layout.value):'');
const partition=computed(()=>layout.value?projectGraphViewport(layout.value,diagnosticViewport.value,filtered.value):null);
const relationContext=computed(()=>{const counts={filtered:0,otherGroup:0,unresolved:0};for(const edge of partition.value?.edges??[]){if(edge.from==='filtered'||edge.to==='filtered')counts.filtered++;if(edge.from==='other-group'||edge.to==='other-group')counts.otherGroup++;if(edge.from==='unresolved'||edge.to==='unresolved')counts.unresolved++;}return counts;});
const focusedRelations=computed(()=>{if(!layout.value||!relationId.value)return [];const direct=graphDirectRelations(layout.value,relationId.value);return direct?[...direct.predecessors.map(edge=>({key:'before:'+edge.id,direction:'선행',endpoint:edge.from})),...direct.successors.map(edge=>({key:'after:'+edge.id,direction:'후속',endpoint:edge.to}))]:[];});
watch(relationId,()=>{relationPage.value=1;});
const pinnedNode=computed(()=>focusedId.value&&layout.value?.positionById.get(focusedId.value));
const drawnNodes=computed(()=>{const nodes=render.value?.exceeded.nodes?[]:render.value?.nodes??[],pin=pinnedNode.value;return pin&&(!filtered.value||filtered.value.has(pin.id)||focusReturnId.value===pin.id)&&!nodes.some(n=>n.id===pin.id)?[...nodes,pin]:nodes;});
watch(search,()=>{searchPage.value=1;});
watch(status,async()=>{focusReturnId.value=null;if(focusedId.value&&filtered.value&&!filtered.value.has(focusedId.value)){const lostFocus=(document.activeElement as HTMLElement|null)?.dataset?.graphTask===focusedId.value,epoch=generation;focusedId.value=null;relationFocus.value=null;hoveredId.value=null;await nextTick();if(lostFocus&&epoch===generation&&usable.value)pane.value?.focus();}});
function panKey(event:KeyboardEvent){if(event.target!==event.currentTarget)return;const moves:Record<string,[number,number]>={ArrowLeft:[-100,0],ArrowRight:[100,0],ArrowUp:[0,-100],ArrowDown:[0,100],PageUp:[0,-500],PageDown:[0,500],Home:[-Infinity,-Infinity]};const delta=moves[event.key];if(!delta||!pane.value)return;event.preventDefault();pane.value.scrollTo({left:Math.max(0,pane.value.scrollLeft+delta[0]),top:Math.max(0,pane.value.scrollTop+delta[1])});measure();}
const pan=createGraphPan(()=>pane.value,measure);
const {start:startPan,move:movePan,end:endPan}=pan;
function selectTask(id:string,event:MouseEvent){if(pan.blockedClick(event))return;if(usable.value&&!loading.value)emit('select',id);}
function minimapNavigate(event:MouseEvent){const el=minimapCanvas.value;if(!el)return;const rect=el.getBoundingClientRect();if(!layout.value||!pane.value)return;const x=Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width))*layout.value.width,y=Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height))*layout.value.height;pane.value.scrollTo(graphCenteredScroll({x,y,width:0,height:0},zoom.value,pane.value.clientWidth,pane.value.clientHeight));measure();}
function visibility(){hidden.value=document.hidden;}
watch(()=>[props.projectId,props.dagId,props.sourceKey,usable.value] as const,(next,prior)=>{pipeline.setBackground(!usable.value);const resume=!!prior&&next[3]&&next[0]===prior[0]&&next[1]===prior[1]&&!!props.selectedId&&!!props.detailOpen;void load(resume);},{immediate:true});
let observer:ResizeObserver|null=null,unbindZoom:(()=>void)|undefined;
watch(pane,el=>{unbindZoom?.();observer?.disconnect();if(el){unbindZoom=gestureZoom.bind(el);observer=new ResizeObserver(measure);observer.observe(el);measure();}});
onMounted(()=>document.addEventListener('visibilitychange',visibility));
onBeforeUnmount(()=>{rememberView();if(diagnosticTimer)clearTimeout(diagnosticTimer);stop();unbindZoom?.();pipeline.dispose();observer?.disconnect();document.removeEventListener('visibilitychange',visibility);});
function currentIdentity(){return usable.value&&!loading.value?layout.value?.identity:null;}
function isRevalidating(){return loading.value||!layout.value||!usable.value;}
defineExpose({openGroup:project,reveal,currentIdentity,focusOnly,isRevalidating});
</script>
<template>
 <section class="complete-graph" data-testid="complete-task-graph" @keydown="dismissRelations">
  <h2>관계 그래프</h2>
  <div class="graph-toolbar"><span>그룹 기준</span><div role="group" aria-label="그래프 그룹 기준"><button v-for="mode in ([['prefix','접두사'],['phase','Phase'],['ungrouped','묶지 않음']] as const)" :key="mode[0]" :aria-pressed="grouping===mode[0]" :disabled="loading" @click="changeGrouping(mode[0])">{{mode[1]}}</button></div><label class="graph-search"><span class="sr-only">전체 작업 ID 또는 이름 검색</span><input v-model="search" placeholder="작업 ID 또는 이름 검색" maxlength="512"/></label><button :aria-expanded="showFilter" @click="showFilter=!showFilter">필터</button><button @click="fit">전체 맞춤</button></div>
  <label v-if="showFilter&&groupKey!==null" class="graph-filter">선언 상태 <select v-model="status"><option value="all">전체</option><option v-for="item in statuses" :key="JSON.stringify(item)" :value="'status:'+(item??'')">{{item??'미선언'}}</option></select></label><p v-else-if="showFilter" class="muted">개요는 전체 선언 집계입니다. 그룹을 열면 작업 상태로 표시를 좁힐 수 있습니다.</p>
  <section v-if="search.trim()" class="graph-results" aria-label="전체 소스 검색 결과"><p role="status" aria-atomic="true">{{matches.length}}개 결과<span v-if="matches.length>100"> · {{searchPage}} / {{Math.ceil(matches.length/100)}}페이지</span></p><button v-for="node in matches.slice((searchPage-1)*100,searchPage*100)" :key="node.id" @click="reveal(node.id)">{{node.id}} · {{node.title??'제목 미선언'}}</button><div v-if="matches.length>100"><button :disabled="searchPage===1" @click="searchPage--">검색 이전</button><button :disabled="searchPage*100>=matches.length" @click="searchPage++">검색 다음</button></div></section>
  <p v-if="!current" role="status">현재 연결과 근거를 확인할 수 없습니다</p><p v-else-if="loading" role="status">전체 그래프를 읽고 있습니다…</p><p v-if="error" role="alert">{{error}} <button @click="load()">다시 읽기</button></p>
  <p v-if="snapshot?.metadata.coverage.state==='partial'" class="notice warning" role="status">일부 근거만 확인됨 · {{snapshot.metadata.coverage.reasons.join(', ')}}. 표시 집계가 전체 작업을 뜻하지 않습니다.</p>
  <p v-if="dateError" class="muted" role="status">연결 커밋 날짜 근거를 확인하지 못했습니다</p>
  <section v-if="layout&&!loading&&sourceCycles.length" class="graph-cycles" aria-label="실제 작업 순환 근거">
   <p role="status">작업 순환 {{sourceCycles.length}}개가 확인되었습니다. 그룹 집계의 양방향 화살표와 별도인 실제 작업 의존 관계입니다.</p>
   <details><summary>순환 작업 ID 확인</summary><p>순환 {{cyclePage}} / {{sourceCycles.length}} · {{activeCycle.length}}개 작업</p><p>{{activeCycle.slice((cycleMemberPage-1)*20,cycleMemberPage*20).join(', ')}}</p>
    <nav v-if="activeCycle.length>20" aria-label="순환 작업 ID 페이지"><button :disabled="cycleMemberPage===1" @click="cycleMemberPage--">이전 순환 작업</button><span>{{cycleMemberPage}} / {{Math.ceil(activeCycle.length/20)}}</span><button :disabled="cycleMemberPage*20>=activeCycle.length" @click="cycleMemberPage++">다음 순환 작업</button></nav>
    <nav v-if="sourceCycles.length>1" aria-label="작업 순환 페이지"><button :disabled="cyclePage===1" @click="cyclePage--">이전 순환</button><button :disabled="cyclePage===sourceCycles.length" @click="cyclePage++">다음 순환</button></nav>
   </details>
  </section>
  <template v-if="layout&&!loading">
   <p v-if="!layout.groups.length" class="empty-state" role="status">확인된 작업 선언이 없습니다</p>
   <TaskGraphOverview ref="overview" v-else-if="groupKey===null" :layout="layout" :dates="dates" :ordered-group-keys="orderedGroups" @open-group="key=>project(key)"/>
   <section v-else class="group-workspace" data-testid="continuous-group-graph"><button class="back-overview" @click="project(null)">‹ 전체</button><div class="group-heading"><h3>{{labels.get(groupKey)}} <small>{{layout.nodes.length}}개 작업</small></h3><GraphInfoTooltip kind="date" :label="labels.get(groupKey)+' 최근 연결 커밋 날짜 '+graphDateShortLabel(groupDate,dateYear)">{{graphDateShortLabel(groupDate,dateYear)}}<template #content><strong>최근 연결 커밋</strong><template v-if="groupDate?.latest"><p>{{linkedDateKst(groupDate.latest.committerAtUtc)}}</p><p>{{groupDate.latest.taskId}} · {{groupDate.latest.sha}}</p><p>{{groupDate.latest.verifiedCommitUrl}}</p></template><p v-else>확인된 연결 커밋 없음</p><template v-if="groupDate"><p>날짜 확인 {{groupDate.coverage.tasks.resolved}}/{{groupDate.coverage.tasks.total}}개 · 참조 없음 {{groupDate.coverage.tasks.noReference}} · 미확인 {{groupDate.coverage.tasks.unresolved}}</p><p>참조 확인 {{groupDate.coverage.references.resolved}}/{{groupDate.coverage.references.total}}개 · 미해결 {{groupDate.coverage.references.unresolved}}</p><small>{{groupDate.state==='partial'?'일부 확인 · ':''}}{{groupDate.coverage.inspection==='complete'?'확인된 연결 기록 기준':'참조 조사 미완료'}} · 작업일·완료일 아님</small></template></template></GraphInfoTooltip><span v-if="dateYear" class="date-year">{{dateYear}}</span></div><div class="group-status"><GraphInfoTooltip kind="status" :label="labels.get(groupKey)+' 선언 상태, 총 '+layout.nodes.length+'개. '+groupStatuses.map(s=>s.label+' '+s.count).join(', ')"><span class="status-bar" aria-hidden="true"><i v-for="item in groupStatuses" :key="JSON.stringify(item.status)" :class="'status-'+item.tone" :style="{width:item.count/layout.nodes.length*100+'%'}"/></span><template #content><strong>선언 상태</strong><p v-for="item in groupStatuses" :key="JSON.stringify(item.status)">{{item.label}} {{item.count}}<span v-if="item.status&&item.label!==item.status"> ({{item.status}})</span></p><small>실행 검증 결과 아님</small></template></GraphInfoTooltip></div><div class="graph-controls" data-relation-controls @focusout="leaveRelationControls" @mouseenter="keepHover" @mouseleave="leaveNode"><span>선행 → 후속 · {{relationId?relationId+(hoveredId?'에 마우스를 올린 상태':relationFocus?'에 키보드 초점':' 선택'):'작업 미선택'}}</span><strong v-if="relationSet" class="relation-count predecessor" role="status">직접 선행 {{relationSet.predecessors}}</strong><strong v-if="relationSet" class="relation-count successor" role="status">직접 후속 {{relationSet.successors}}</strong><button v-if="relationSet" data-relation-dismiss-focus :aria-expanded="showRelations" @click="showRelations=!showRelations">전체 직접 관계</button><button v-if="relationReturn" @click="returnRelation">이전 관계 위치로</button><button :disabled="!selectedId" @click="selectedId&&reveal(selectedId)">선택 작업으로</button><button aria-label="그래프 축소" @click="setZoom(zoom/1.25)">−</button><button @click="setZoom(1)">{{zoom<.01?(zoom*100).toFixed(3):Math.round(zoom*100)}}%</button><button aria-label="그래프 확대" @click="setZoom(zoom*1.25)">+</button><button @click="fit">전체 맞춤</button></div>
    <p v-if="render?.exceeded.nodes||render?.exceeded.routes" class="notice warning" role="status">현재 범위에 작업 {{render.counts.visibleNodes}}개·연결 {{render.counts.intersectingRoutes}}개가 겹칩니다. 렌더링 안전 상한을 넘어 연결 그림을 일시 중지했습니다. 작업 카드도 상한을 넘으면 검색으로 이동한 작업만 표시합니다. 확대하거나 상태 필터로 범위를 좁히거나 검색으로 작업을 찾아 주세요. 현재 범위의 연결 {{render.counts.intersectingRoutes}}개는 그리지 않았습니다. 전체 관계 원본은 유지됩니다.</p><section v-if="(showRelations||render?.exceeded.nodes||render?.exceeded.routes)&&relationId" class="density-relations" @mouseenter="keepHover" @mouseleave="leaveNode" data-relation-controls @focusout="leaveRelationControls" aria-label="작업 전체 직접 관계"><strong>{{relationId}} 직접 관계 {{relationSet?.edges.size??0}}개</strong><small v-if="focusedRelations.length!==(relationSet?.edges.size??0)"> · 선행·후속 역할 항목 {{focusedRelations.length}}개 (같은 관계가 두 역할에 포함될 수 있음)</small><ul><li v-for="relation in focusedRelations.slice((relationPage-1)*20,relationPage*20)" :key="relation.key">{{relation.direction}} <button v-if="relation.endpoint.kind==='node'" @click="followRelation(relation.endpoint.id)">{{relation.endpoint.id}}로 이동</button><span v-else>{{relation.endpoint.id}} · 원문 참조 미해결 ({{relation.endpoint.reason}})</span></li></ul><nav v-if="focusedRelations.length>20" aria-label="직접 관계 페이지"><button :disabled="relationPage===1" @click="relationPage--">관계 이전</button><span>{{relationPage}} / {{Math.ceil(focusedRelations.length/20)}}</span><button :disabled="relationPage*20>=focusedRelations.length" @click="relationPage++">관계 다음</button></nav></section>
    <p v-if="focusReturnId" role="status">{{focusReturnId}} · 현재 필터 밖 · 상세에서 돌아온 작업입니다. 초점이 이동하면 다시 숨깁니다.</p><p v-if="selectionNotice" role="status">{{selectionNotice}}</p><p v-if="filtered&&partition?.counts.nodes.filtered===layout.nodes.length" role="status">현재 상태 필터에 맞는 작업이 없습니다. <button @click="status='all'">필터 초기화</button></p><div class="canvas-region"><div ref="pane" class="continuous-pane" tabindex="0" aria-label="연속 작업 그래프, 가로와 세로 스크롤" @scroll="measure" @keydown="panKey" @pointerdown="startPan" @pointermove="movePan" @pointerup="endPan" @pointercancel="endPan" @lostpointercapture="endPan" @pointerleave="pan.leave"><div :style="{width:layout.width*zoom+'px',height:layout.height*zoom+'px',position:'relative'}"><div v-if="render" class="graph-world" :style="{width:layout.width+'px',height:layout.height+'px',transform:`scale(${zoom})`}"><span v-for="column in layout.columns" :key="column.depth" class="depth-heading" :style="{left:column.x+'px'}">깊이 {{column.depth}}</span><svg v-if="!render.exceeded.nodes&&!render.exceeded.routes" :width="layout.width" :height="layout.height" aria-hidden="true"><defs><marker v-for="(color,role) in markerTones" :key="role" :id="marker+'-'+role" :style="{color}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor"/></marker></defs><path v-for="edge in render.routes" :key="edge.id" :d="graphRoutePath(edge)" :class="edgeRelationClass(edge.id)" fill="none" stroke="currentColor" :marker-end="`url(#${edgeMarker(edge.id)})`"/></svg><button v-for="node in drawnNodes" :key="node.id" class="graph-task" :class="['tone-'+graphDeclaredStatus(layout.index.nodeById.get(node.id)?.declaredStatus??null).tone,nodeRelationClass(node.id),{'is-selected':selectedId===node.id}]" :style="{left:node.x+'px',top:node.y+'px',width:node.width+'px',height:node.height+'px'}" :data-graph-task="node.id" :aria-label="node.id+' '+(layout.index.nodeById.get(node.id)?.title??'제목 미선언')+' 선언 상태 '+(layout.index.nodeById.get(node.id)?.declaredStatus??'미선언')+' 상세 열기'" @mouseenter="enterNode(node.id)" @mouseleave="leaveNode" @focus="focusNode(node.id)" @blur="blurNode" :aria-pressed="selectedId===node.id" :aria-description="[relationLabel(node.id)?relationId+'의 직접 '+relationLabel(node.id):'',focusReturnId===node.id?'현재 필터 밖 · 상세에서 돌아온 작업':''].filter(Boolean).join('. ')||undefined" @click="selectTask(node.id,$event)"><strong>{{node.id}}</strong><small v-if="relationLabel(node.id)">{{relationLabel(node.id)}}</small><span>{{layout.index.nodeById.get(node.id)?.title??'제목 미선언'}}</span></button></div></div></div>
    <section v-if="boundaryRelations.length" class="boundary-relations" data-relation-controls @focusout="leaveRelationControls" aria-label="화면 밖 직접 관계" @mouseenter="keepHover" @mouseleave="leaveNode"><div v-for="relation in boundaryRelations.slice((boundaryPage-1)*6,boundaryPage*6)" :key="relation.key" class="boundary-chip" :class="'relation-'+relation.role"><button v-if="relation.navigable" @click="followRelation(relation.endpoint.id)">{{relation.role==='predecessor'?'선행':'후속'}} {{relation.endpoint.id}} {{relation.arrow}}<small>{{relation.label}}</small></button><span v-else>{{relation.role==='predecessor'?'선행':'후속'}} {{relation.endpoint.id}}<small>{{relation.label}}</small></span></div><nav v-if="boundaryRelations.length>6" aria-label="화면 밖 직접 관계 페이지"><button :disabled="boundaryPage===1" @click="boundaryPage--">이전 관계</button><span>{{boundaryPage}} / {{Math.ceil(boundaryRelations.length/6)}} · {{boundaryRelations.length}}개</span><button :disabled="boundaryPage*6>=boundaryRelations.length" @click="boundaryPage++">다음 관계</button></nav></section></div>
    <div class="canvas-footer"><p class="graph-range">현재 화면 {{render?.counts.visibleNodes??0}}/{{layout.nodes.length}}개 · 화면 밖 {{layout.nodes.length-(partition?.counts.nodes.filtered??0)-(render?.counts.visibleNodes??0)}}개 · 필터 숨김 {{partition?.counts.nodes.filtered??0}}개<br/>↓ 아래로 같은 깊이의 작업 · → 오른쪽으로 후속 깊이 · 방향키 / 드래그로 이동</p><button class="graph-minimap" aria-label="전체 그래프 미니맵, 클릭한 위치로 이동, 방향키로 이동" @keydown="panKey" @click="minimapNavigate"><span>전체 {{layout.nodes.length}} · 현재 위치</span><svg ref="minimapCanvas" :viewBox="`0 0 ${layout.width} ${layout.height}`" preserveAspectRatio="none" aria-hidden="true"><path :d="miniPath" stroke="currentColor" fill="none" :stroke-width="Math.max(2,layout.height/90)"/><rect :x="viewport.x" :y="viewport.y" :width="Math.min(viewport.width,layout.width)" :height="Math.min(viewport.height,layout.height)" fill="none" stroke="currentColor" :stroke-width="Math.max(4,layout.width/100)"/></svg></button></div>
    <p class="graph-range">전체 소스 관계 <span v-if="diagnosticViewport!==viewport">(위치 집계 갱신 중)</span>{{partition?.counts.edges.total??0}}개 · 화면 내 {{partition?.counts.edges.internal??0}} · 화면 경계 {{partition?.counts.edges.boundary??0}} · 양 끝 화면 밖 {{partition?.counts.edges.outside??0}}<br/>필터 밖 작업 연결 {{relationContext.filtered}} · 다른 그룹 연결 {{relationContext.otherGroup}} · 원문 참조 미해결 {{relationContext.unresolved}} (문맥별 수는 겹칠 수 있음)</p>
   </section>
  </template>
 </section>
</template>
